using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Threading;
using System.Threading.Tasks;

namespace CryptoLib
{
    public sealed class RateLimitedCryptoService : IDisposable
    {
        private readonly SemaphoreSlim _semaphore = new SemaphoreSlim(1, 1);
        private readonly Dictionary<string, int> _attemptCounts = new Dictionary<string, int>();
        private readonly Dictionary<string, DateTime> _lockoutUntil = new Dictionary<string, DateTime>();
        private const int MaxAttempts = 5;
        private const int LockoutSeconds = 300;
        private const int MaxRetries = 3;
        private volatile int _operationState = 0; // 0=idle, 1=encrypting, 2=finalizing
        private byte[] _sessionKey;
        private readonly object _keyLock = new object();
        private bool _disposed = false;

        public RateLimitedCryptoService()
        {
            _sessionKey = GenerateSessionKey();
            AppDomain.CurrentDomain.ProcessExit += OnProcessExit;
            Console.CancelKeyPress += OnCancelKeyPress;
        }

        private byte[] GenerateSessionKey()
        {
            byte[] key = new byte[32];
            using (var rng = RandomNumberGenerator.Create())
            {
                rng.GetBytes(key);
            }
            return key;
        }

        private void OnProcessExit(object sender, EventArgs e)
        {
            CleanupState();
        }

        private void OnCancelKeyPress(object sender, ConsoleCancelEventArgs e)
        {
            e.Cancel = true;
            CleanupState();
        }

        private void CleanupState()
        {
            // Signal handler: only cleanup if idle, otherwise defer
            if (Interlocked.CompareExchange(ref _operationState, 0, 0) != 0)
                return; // Operation in progress, don't mutate key
            lock (_keyLock)
            {
                if (_sessionKey != null)
                {
                    Array.Clear(_sessionKey, 0, _sessionKey.Length);
                    _sessionKey = GenerateSessionKey();
                }
            }
        }

        public async Task<byte[]> EncryptWithRetry(string clientId, byte[] plaintext)
        {
            if (_disposed) throw new ObjectDisposedException(nameof(RateLimitedCryptoService));
            if (string.IsNullOrEmpty(clientId)) throw new ArgumentNullException(nameof(clientId));
            if (plaintext == null || plaintext.Length == 0) throw new ArgumentNullException(nameof(plaintext));

            await _semaphore.WaitAsync();
            try
            {
                if (IsLockedOut(clientId))
                    throw new InvalidOperationException($"Client {clientId} is locked out.");

                IncrementAttempt(clientId);
            }
            finally
            {
                _semaphore.Release();
            }

            return await ExecuteWithRetry(() => PerformEncryption(plaintext));
        }

        private async Task<byte[]> ExecuteWithRetry(Func<byte[]> operation)
        {
            int retries = 0;
            while (true)
            {
                try
                {
                    // Wait until state is idle before proceeding
                    SpinWait.SpinUntil(() => Interlocked.CompareExchange(ref _operationState, 1, 0) == 0, 5000);

                    byte[] result = operation();
                    Interlocked.Exchange(ref _operationState, 0);
                    return result;
                }
                catch (CryptographicException) when (retries < MaxRetries)
                {
                    retries++;
                    // State may have been reset by signal handler between
                    // our check and the operation - retry with backoff
                    Interlocked.Exchange(ref _operationState, 0);
                    await Task.Delay(100 * retries);
                }
            }
        }

        private byte[] PerformEncryption(byte[] plaintext)
        {
            byte[] currentKey;
            lock (_keyLock)
            {
                currentKey = new byte[_sessionKey.Length];
                Buffer.BlockCopy(_sessionKey, 0, currentKey, 0, _sessionKey.Length);
            }

            using (var aes = Aes.Create())
            {
                aes.Key = currentKey;
                aes.GenerateIV();
                aes.Mode = CipherMode.CBC;
                aes.Padding = PaddingMode.PKCS7;

                // Transition to finalizing state
                Interlocked.Exchange(ref _operationState, 2);

                using (var encryptor = aes.CreateEncryptor())
                {
                    byte[] ciphertext = encryptor.TransformFinalBlock(plaintext, 0, plaintext.Length);
                    byte[] result = new byte[aes.IV.Length + ciphertext.Length];
                    Buffer.BlockCopy(aes.IV, 0, result, 0, aes.IV.Length);
                    Buffer.BlockCopy(ciphertext, 0, result, aes.IV.Length, ciphertext.Length);
                    return result;
                }
            }
        }

        public async Task<byte[]> DecryptWithRetry(string clientId, byte[] ciphertext)
        {
            if (_disposed) throw new ObjectDisposedException(nameof(RateLimitedCryptoService));
            if (string.IsNullOrEmpty(clientId)) throw new ArgumentNullException(nameof(clientId));
            if (ciphertext == null || ciphertext.Length < 17) throw new ArgumentException("Invalid ciphertext");

            await _semaphore.WaitAsync();
            try
            {
                if (IsLockedOut(clientId))
                    throw new InvalidOperationException($"Client {clientId} is locked out.");

                IncrementAttempt(clientId);
            }
            finally
            {
                _semaphore.Release();
            }

            return await ExecuteWithRetry(() => PerformDecryption(ciphertext));
        }

        private byte[] PerformDecryption(byte[] ciphertext)
        {
            byte[] currentKey;
            lock (_keyLock)
            {
                currentKey = new byte[_sessionKey.Length];
                Buffer.BlockCopy(_sessionKey, 0, currentKey, 0, _sessionKey.Length);
            }

            byte[] iv = new byte[16];
            Buffer.BlockCopy(ciphertext, 0, iv, 0, 16);
            byte[] encrypted = new byte[ciphertext.Length - 16];
            Buffer.BlockCopy(ciphertext, 16, encrypted, 0, encrypted.Length);

            using (var aes = Aes.Create())
            {
                aes.Key = currentKey;
                aes.IV = iv;
                aes.Mode = CipherMode.CBC;
                aes.Padding = PaddingMode.PKCS7;

                Interlocked.Exchange(ref _operationState, 2);

                using (var decryptor = aes.CreateDecryptor())
                {
                    return decryptor.TransformFinalBlock(encrypted, 0, encrypted.Length);
                }
            }
        }

        private bool IsLockedOut(string clientId)
        {
            if (_lockoutUntil.TryGetValue(clientId, out DateTime until))
            {
                if (DateTime.UtcNow < until) return true;
                _lockoutUntil.Remove(clientId);
                _attemptCounts.Remove(clientId);
            }
            return false;
        }

        private void IncrementAttempt(string clientId)
        {
            if (!_attemptCounts.ContainsKey(clientId))
                _attemptCounts[clientId] = 0;

            _attemptCounts[clientId]++;
            if (_attemptCounts[clientId] >= MaxAttempts)
            {
                _lockoutUntil[clientId] = DateTime.UtcNow.AddSeconds(LockoutSeconds);
            }
        }

        public void Dispose()
        {
            if (!_disposed)
            {
                _disposed = true;
                lock (_keyLock)
                {
                    if (_sessionKey != null)
                        Array.Clear(_sessionKey, 0, _sessionKey.Length);
                }
                _semaphore.Dispose();
                AppDomain.CurrentDomain.ProcessExit -= OnProcessExit;
                Console.CancelKeyPress -= OnCancelKeyPress;
            }
        }
    }
}
